typedef int (*rar3_hash_fn)(const rar3_layout*, const uint8_t*, int, uint8_t*);

static int rar3_selftest(rar3_hash_fn hash)
{
    rar3_layout* L = (rar3_layout*)malloc(sizeof *L);
    if (!L) return 0;
    uint8_t pws[32 * RAR3_MAXLEN], out[32 * 36];
    int ok = 1;
    for (int k = 0; k < 4 && ok; k++)
    {
        int len = RAR3_TEST_LENGTHS[k];
        for (int i = 0; i < 32; i++)
            for (int q = 0; q < len; q++) pws[i * len + q] = (uint8_t)(0x21 + (i * 17 + q * 7) % 94);
        rar3_layout_init(L, RAR3_TEST_SALT, pws, len, 32);
        ok = hash(L, pws, 32, out) && memcmp(out, RAR3_TEST_ANSWERS[k], sizeof out) == 0;
    }
    free(L);
    return ok;
}
